 void top(String title,View.OnClickListener back){LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);h.setPadding(d(10),0,d(12),0);TextView b=tv("‹",36,TEXT);b.setGravity(17);h.addView(b,new LinearLayout.LayoutParams(d(48),d(58)));TextView t=tv(title,20,TEXT);t.setTypeface(null,1);h.addView(t,new LinearLayout.LayoutParams(0,d(58),1));root.addView(h);b.setOnClickListener(back);}
 void home(){shell();LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);h.setPadding(d(15),0,d(10),0);TextView logo=tv("🔐",25,BLUE);h.addView(logo,new LinearLayout.LayoutParams(d(45),d(55)));TextView t=tv("My Password Vault",19,TEXT);t.setTypeface(null,1);h.addView(t,new LinearLayout.LayoutParams(0,d(55),1));TextView l=tv("🔒",20,MUTED);h.addView(l,new LinearLayout.LayoutParams(d(45),d(55)));root.addView(h);l.setOnClickListener(v->{master="";lock();});search=in("🔎  ค้นหา ชื่อรายการ, username หรือหมายเหตุ...");LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,d(50));sp.setMargins(d(14),d(3),d(14),d(8));root.addView(search,sp);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){render(s.toString());}public void afterTextChanged(Editable e){}});list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView sv=new ScrollView(this);sv.addView(list);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));Button add=bt("＋  เพิ่มรายการ");LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,d(54));ap.setMargins(d(14),d(6),d(14),d(6));root.addView(add,ap);add.setOnClickListener(v->edit(null));LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);nav.setBackgroundColor(Color.WHITE);String[] n={"รายการ","หมวดหมู่","สำรองข้อมูล","ตั้งค่า"};for(int i=0;i<4;i++){TextView q=tv(n[i],11,MUTED);q.setGravity(17);final int z=i;nav.addView(q,new LinearLayout.LayoutParams(0,d(54),1));q.setOnClickListener(v->{if(z==0)home();else if(z==1)categories();else if(z==2)backup();else settings();});}root.addView(nav);render("");}
 void render(String q){list.removeAllViews();q=q.toLowerCase(Locale.ROOT);int no=0;for(VaultStore.Entry e:store.entries(master)){if(!(e.title+" "+e.user+" "+e.note+" "+e.category).toLowerCase(Locale.ROOT).contains(q))continue;no++;LinearLayout c=card();c.setOrientation(LinearLayout.HORIZONTAL);c.setGravity(Gravity.CENTER_VERTICAL);c.setPadding(d(10),d(5),d(8),d(5));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,d(76));cp.setMargins(d(12),d(4),d(12),d(4));list.addView(c,cp);TextView num=tv(String.format(Locale.US,"%02d",no),12,BLUE);num.setGravity(17);num.setBackground(bg(Color.rgb(230,239,255),40));c.addView(num,new LinearLayout.LayoutParams(d(38),d(38)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(d(12),0,0,0);TextView a=tv(e.title,16,TEXT);a.setTypeface(null,1);tx.addView(a,new LinearLayout.LayoutParams(-1,d(31)));tx.addView(tv(e.user.isEmpty()?"ไม่มี Username":e.user,12,MUTED),new LinearLayout.LayoutParams(-1,d(25)));c.addView(tx,new LinearLayout.LayoutParams(0,-1,1));c.addView(tv("›",29,MUTED),new LinearLayout.LayoutParams(d(30),-1));c.setOnClickListener(v->details(e));}if(no==0){TextView z=tv("ยังไม่มีรายการ\nกด “เพิ่มรายการ” เพื่อเริ่มต้น",16,MUTED);z.setGravity(17);list.addView(z,new LinearLayout.LayoutParams(-1,d(160)));}}
 void details(VaultStore.Entry e){shell();top("รายละเอียดรายการ",v->home());LinearLayout b=card();LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.setMargins(d(14),d(8),d(14),d(14));root.addView(b,bp);TextView h=tv(e.title,23,TEXT);h.setTypeface(null,1);b.addView(h,new LinearLayout.LayoutParams(-1,d(50)));field(b,"Username",e.user,true,false);field(b,"Password",e.pass,true,true);field(b,"บันทึกเพิ่มเติม",e.note,false,false);field(b,"หมวดหมู่",e.category,false,false);Button ed=bt("✎  แก้ไข");b.addView(ed,new LinearLayout.LayoutParams(-1,d(52)));ed.setOnClickListener(v->edit(e));Button del=bt("ลบรายการ");del.setTextColor(Color.rgb(190,45,60));del.setBackground(line());LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(-1,d(52));dp.setMargins(0,d(10),0,0);b.addView(del,dp);del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("ลบรายการ?").setMessage(e.title).setNegativeButton("ยกเลิก",null).setPositiveButton("ลบ",(x,w)->{try{store.delete(master,e.id);home();}catch(Exception z){toast("ลบไม่สำเร็จ");}}).show());}
