 void edit(VaultStore.Entry old){VaultStore.Entry e=old==null?VaultStore.newEntry():new VaultStore.Entry(old.id,old.title,old.user,old.pass,old.note,old.category);shell();top(old==null?"เพิ่มรายการ":"แก้ไขรายการ",v->home());ScrollView sv=new ScrollView(this);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(d(16),d(4),d(16),d(18));sv.addView(b);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));EditText a=in("ชื่อรายการ");a.setText(e.title);b.addView(tv("รายการ",12,MUTED));b.addView(a,new LinearLayout.LayoutParams(-1,d(52)));EditText u=in("Username");u.setText(e.user);b.addView(tv("Username",12,MUTED));b.addView(u,new LinearLayout.LayoutParams(-1,d(52)));EditText p=in("Password");p.setText(e.pass);p.setInputType(129);b.addView(tv("Password",12,MUTED));b.addView(p,new LinearLayout.LayoutParams(-1,d(52)));EditText n=in("บันทึกเพิ่มเติม");n.setSingleLine(false);n.setMinLines(3);n.setGravity(Gravity.TOP);n.setText(e.note);b.addView(tv("บันทึกเพิ่มเติม",12,MUTED));b.addView(n,new LinearLayout.LayoutParams(-1,d(90)));EditText cat=in("เช่น ทั่วไป / อีเมล / ธนาคาร");cat.setText(e.category);b.addView(tv("หมวดหมู่",12,MUTED));b.addView(cat,new LinearLayout.LayoutParams(-1,d(52)));Button save=bt("💾  บันทึก");LinearLayout.LayoutParams sb=new LinearLayout.LayoutParams(-1,d(54));sb.setMargins(0,d(18),0,0);b.addView(save,sb);save.setOnClickListener(v->{e.title=a.getText().toString().trim();e.user=u.getText().toString();e.pass=p.getText().toString();e.note=n.getText().toString();e.category=cat.getText().toString();if(e.title.isEmpty()){a.setError("กรุณาระบุชื่อรายการ");return;}try{if(old==null)store.add(master,e);else store.update(master,e);home();}catch(Exception x){toast("บันทึกไม่สำเร็จ");}});}
 void categories(){shell();top("หมวดหมู่",v->home());LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(d(14),d(8),d(14),d(20));root.addView(b);Map<String,Integer> m=new LinkedHashMap<>();for(VaultStore.Entry e:store.entries(master)){String c=e.category==null||e.category.isEmpty()?"ทั่วไป":e.category;m.put(c,m.getOrDefault(c,0)+1);}if(m.isEmpty())b.addView(tv("ยังไม่มีหมวดหมู่",15,MUTED),new LinearLayout.LayoutParams(-1,d(100)));for(Map.Entry<String,Integer>x:m.entrySet()){LinearLayout r=card();r.setOrientation(LinearLayout.HORIZONTAL);r.setGravity(Gravity.CENTER_VERTICAL);TextView n=tv("▦  "+x.getKey(),16,TEXT);r.addView(n,new LinearLayout.LayoutParams(0,d(62),1));r.addView(tv(String.valueOf(x.getValue()),14,MUTED),new LinearLayout.LayoutParams(d(40),d(62)));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,d(68));rp.setMargins(0,d(5),0,d(5));b.addView(r,rp);}}
 void backup(){shell();top("สำรองและกู้คืน",v->home());LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(d(14),d(8),d(14),d(20));ScrollView sv=new ScrollView(this);sv.addView(b);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));TextView info=tv("🔐 Backup เข้ารหัสด้วย Master Password\nเลือก Google Drive, NAS หรือโฟลเดอร์ปลายทางได้จากตัวเลือกไฟล์",14,TEXT);info.setPadding(d(14),d(12),d(14),d(12));info.setBackground(bg(Color.rgb(231,241,255),15));b.addView(info,new LinearLayout.LayoutParams(-1,d(82)));Button ex=bt("☁  สำรองข้อมูล / เลือกที่เก็บ");b.addView(ex,new LinearLayout.LayoutParams(-1,d(54)));ex.setOnClickListener(v->exportFile());Button im=bt("♻  กู้คืนข้อมูล / เลือกไฟล์ Backup");im.setTextColor(BLUE);im.setBackground(line());LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,d(54));ip.setMargins(0,d(10),0,d(18));b.addView(im,ip);im.setOnClickListener(v->importFile());TextView sh=tv("NAS / Synology",19,TEXT);sh.setTypeface(null,1);b.addView(sh,new LinearLayout.LayoutParams(-1,d(40)));TextView nt=tv("ไม่ต้องกรอก IP หรือรหัสผ่าน NAS ในแอป\nตอนสำรอง/กู้คืนให้เลือกตำแหน่ง NAS จากตัวจัดการไฟล์ของเครื่อง หาก NAS ถูกเพิ่มไว้ในแอปไฟล์",13,MUTED);b.addView(nt,new LinearLayout.LayoutParams(-1,d(70)));}
 void exportFile(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/octet-stream");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"MyPasswordVault_Backup.mpv");startActivityForResult(i,10);}
 void importFile(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,11);}
 @Override protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(c!=RESULT_OK||data==null)return;try{if(r==10){String x=store.encryptedBackup(master);try(OutputStream o=getContentResolver().openOutputStream(data.getData())){if(o==null)throw new IOException("เปิดไฟล์ปลายทางไม่ได้");o.write(x.getBytes(StandardCharsets.UTF_8));}toast("Backup สำเร็จ");}else if(r==11){askBackupPassword(readText(data.getData()));}}catch(Exception e){toast("ดำเนินการไม่สำเร็จ: "+e.getMessage());}}
 String readText(android.net.Uri uri)throws Exception{StringBuilder s=new StringBuilder();InputStream raw=getContentResolver().openInputStream(uri);if(raw==null)throw new IOException("เปิดไฟล์ไม่ได้");try(InputStream in=raw;BufferedReader br=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String z;while((z=br.readLine())!=null)s.append(z).append('\n');}return s.toString();}
 void askBackupPassword(String backup){EditText p=in("Master Password ที่ใช้สร้าง Backup");p.setInputType(129);LinearLayout box=new LinearLayout(this);box.setPadding(d(6),d(4),d(6),0);box.addView(p,new LinearLayout.LayoutParams(-1,d(54)));new AlertDialog.Builder(this).setTitle("รหัสผ่านของ Backup").setMessage("กรุณาใส่ Master Password เดิมที่ใช้ตอนกด Backup\n\nถ้าคุณเปลี่ยน Master Password หลังติดตั้งใหม่ ก็ยัง Restore ได้").setView(box).setNegativeButton("ยกเลิก",null).setPositiveButton("ตรวจสอบและกู้คืน",(d,w)->{String bp=p.getText().toString();if(bp.isEmpty()){toast("กรุณากรอกรหัสผ่าน Backup");return;}confirmRestore(backup,bp);}).show();}
 void confirmRestore(String backup,String backupPassword){new AlertDialog.Builder(this).setTitle("ยืนยันการกู้คืน").setMessage("ข้อมูลในเครื่องจะถูกแทนที่ด้วย Backup นี้\n\nระบบจะตรวจสอบรหัสผ่านและข้อมูลก่อน จากนั้นจะเข้ารหัสใหม่ด้วย Master Password ปัจจุบัน").setNegativeButton("ยกเลิก",null).setPositiveButton("กู้คืน",(d,w)->{try{store.restoreEncryptedBackup(backup,backupPassword,master);toast("กู้คืนสำเร็จ");home();}catch(Exception e){toast("กู้คืนไม่สำเร็จ: "+friendlyRestoreError(e));}}).show();}
 String friendlyRestoreError(Exception e){String m=e.getMessage();if(m==null)return "ไฟล์หรือรหัสผ่านไม่ถูกต้อง";if(m.contains("AEADBadTag")||m.contains("bad tag")||m.contains("IllegalArgumentException"))return "รหัสผ่าน Backup ไม่ถูกต้อง หรือไฟล์เสียหาย";if(m.contains("JSON"))return "Backup เสียหายหรือรูปแบบไม่ถูกต้อง";return m;}
 void settings(){shell();top("ตั้งค่า",v->home());LinearLayout b=card();LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.setMargins(d(14),d(10),d(14),d(14));root.addView(b,bp);b.addView(tv("🔐 ความปลอดภัย",19,TEXT),new LinearLayout.LayoutParams(-1,d(48)));Button l=bt("🔒 ล็อกแอปทันที");b.addView(l,new LinearLayout.LayoutParams(-1,d(52)));l.setOnClickListener(v->{master="";lock();});TextView note=tv("V2.2\nข้อมูล Vault เข้ารหัสในเครื่อง\nBackup/Restore ใช้ตัวเลือกไฟล์ของ Android จึงสามารถเลือก Google Drive หรือ NAS ได้ตามที่เครื่องรองรับ",13,MUTED);note.setPadding(0,d(18),0,0);b.addView(note,new LinearLayout.LayoutParams(-1,d(120)));}
